// packages/warehouse/src/cache-key.ts
//
// The corpus is a deterministic PROJECTION of (pack, the byte-determining params, the generator version).
// So a materialized warehouse is a CACHE: re-materializing the same key is a no-op, and any change is a
// clean rebuild. The key must cover EVERY input that changes generated bytes — miss one and the cache
// silently serves stale data (the exact failure a content-hash is meant to prevent).

import { createHash } from "node:crypto";
import { canonicalJson } from "@dataseed/registry";
import type { BundlePlan } from "@dataseed/core";

/**
 * Explicit generator version. Bump this whenever a change to the GENERATION LOGIC (not its inputs)
 * changes output bytes — a new field, a reordered draw, a new bulk family. It is deliberately a hand-set
 * constant, NOT a source-content hash: a hash over a hand-curated file list silently goes stale the day
 * someone adds an input the list forgot, giving false confidence. A visible constant the author bumps is
 * honest — a stale key is a code-review miss, not a silent corruption.
 */
