/** The plan fields that determine generated bytes — everything the generator reads. asOf IS included
 *  (it anchors every timeline). Excludes derived/display fields (estimatedRecords, perObjectCounts).
 *  `mode`/`withDc` are DELIBERATELY excluded — no pack's generate() currently reads either (see the
 *  header notes on SeedMode/DcMode in scope-params.ts), so folding them in here only bought needless
 *  cache misses: two requests differing ONLY in `mode` or `dc` produce byte-identical records but used
 *  to get different dsIds, defeating the warehouse's whole point of deduping identical corpora. */
function identityParams(plan: BundlePlan): Record<string, unknown> {
  return {
    pack: plan.pack,
    copyMode: plan.copyMode, // foreground copy fill (static/llm/none) determines body bytes → part of identity
    seed: plan.seed,
    asOf: plan.asOf,
    volume: plan.volume,
    population: plan.population,
    bulkDensity: plan.bulkDensity,
    userPoolSize: plan.userPoolSize,
    userProfileName: plan.userProfileName,
    scenarioCounts: plan.scenarioCounts,
    namespacePrefix: plan.namespacePrefix,
  };
}

export interface CorpusKey {
  /**
   * The corpus identity — `ds_<12hex>` of the byte-determining params (INCLUDING asOf, EXCLUDING the
   * generator version). Two corpora with different asOf get DIFFERENT dsIds and coexist; a generator-version
   * bump keeps the same dsId (same logical corpus) so re-materialize rebuilds IN PLACE. NB: this is the
   * warehouse's OWN id — it intentionally differs from the registry's datasetId (which excludes asOf), so
   * distinct-asOf corpora don't collide on one ds_id and silently evict each other.
   */
  dsId: string;
  /** The byte-determining params, hashed — stable across runs with the same inputs. */
  paramsHash: string;
  /** The FULL invalidation key: params + generator version. Re-materialize is a no-op iff this is unchanged. */
  cacheKey: string;
}

/** Compute the content-addressed corpus key for a plan. Pure. */
export function corpusKey(plan: BundlePlan): CorpusKey {
  const paramsHash = createHash("sha256").update(canonicalJson(identityParams(plan))).digest("hex");
  const cacheKey = createHash("sha256").update(paramsHash).update(" ").update(GENERATOR_VERSION).digest("hex").slice(0, 24);
  return { dsId: "ds_" + paramsHash.slice(0, 12), paramsHash, cacheKey };
}
